import{_ as t,o as i,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"FRITZ!Box to MQTT","text":"Home Assistant App für FRITZ!Box-Daten","tagline":"Anruflisten, Live-Anrufe, WLAN, WAN, Telefonbücher und FRITZ!Box-Status per MQTT Discovery in Home Assistant bereitstellen.","actions":[{"theme":"brand","text":"Installation","link":"/projects/fritzbox-to-mqtt/installation"},{"theme":"alt","text":"GitHub","link":"https://github.com/rockbaer2007/ugso-ha-mqtt-addons"}]},"features":[{"icon":"📞","title":"Anrufe und Anrufbeantworter","details":"Anruflisten, Live-Anrufmonitor und Anrufbeantworter AB0 bis AB4 als Home-Assistant-Entitäten."},{"icon":"📶","title":"WLAN und Netzwerk","details":"Schalter für 2,4 GHz, 5 GHz und Gast-WLAN sowie WAN-Verbindungsdaten, IP-Adressen und Linkstatus."},{"icon":"📚","title":"Telefonbücher","details":"Telefonbücher mit auswählbarer Anzeige und optionalen Ausschlüssen für einzelne Namen."},{"icon":"🧭","title":"Mehrere Datenquellen","details":"TR-064, FRITZ!Box-Web-/Lua-Fallbacks und der Live-Anrufmonitor werden kombiniert."},{"icon":"🏠","title":"MQTT Discovery","details":"Home Assistant legt die Sensoren und Schalter automatisch über MQTT Discovery an."},{"icon":"🛠️","title":"Fehlersuche","details":"Eigene Troubleshooting-Seite für Login, TR-064, DNS over TLS, Call Monitor und MQTT."}]},"headers":[],"relativePath":"projects/fritzbox-to-mqtt/index.md","filePath":"projects/fritzbox-to-mqtt/index.md","lastUpdated":1792840662000}'),o={name:"projects/fritzbox-to-mqtt/index.md"};function a(s,e,l,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[r('<h2 id="uberblick" tabindex="-1">Überblick <a class="header-anchor" href="#uberblick" aria-label="Permalink to &quot;Überblick&quot;">​</a></h2><p>FRITZ!Box to MQTT ist eine Home-Assistant-App, die Daten aus einer FRITZ!Box per MQTT Discovery in Home Assistant bereitstellt.</p><p>Der aktuelle veröffentlichte Add-on-Stand liegt im gemeinsamen Repository <code>rockbaer2007/ugso-ha-mqtt-addons</code>. Das frühere Einzelrepository <code>rockbaer2007/fritzbox-to-mqtt</code> ist archiviert.</p><p>Die App nutzt mehrere Quellen, weil nicht jede FRITZ!Box dieselben Schnittstellen gleich ausliefert:</p><ul><li>TR-064 für viele FRITZ!Box-Dienste</li><li>FRITZ!Box-Web-/Lua-Abfragen als Fallback</li><li>den Live-Anrufmonitor auf Port <code>1012</code></li><li>MQTT Discovery für die automatische Entitätserstellung in Home Assistant</li></ul><div class="info custom-block"><p class="custom-block-title">HACS</p><p>Dieses Projekt ist eine Home-Assistant-Supervisor-App. HACS installiert Custom Integrations und Frontend-Karten, aber keine Docker-basierten Supervisor-Apps. Die Installation erfolgt deshalb über die App-Repository-Funktion von Home Assistant.</p></div><h2 id="weitere-seiten" tabindex="-1">Weitere Seiten <a class="header-anchor" href="#weitere-seiten" aria-label="Permalink to &quot;Weitere Seiten&quot;">​</a></h2><ul><li><a href="./installation">Installation</a></li><li><a href="./konfiguration">Konfiguration</a></li><li><a href="./entitaeten">Entitäten</a></li><li><a href="./beispiele">Beispiele</a></li><li><a href="./fehlersuche">Fehlersuche</a></li></ul>',8)])])}const b=t(o,[["render",a]]);export{h as __pageData,b as default};
